def md(rows, head):
    o = ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)]
    for r in rows: o.append("| " + " | ".join(str(x).replace("|", "/").replace("\n", " ") for x in r) + " |")
    return "\n".join(o)
